from fastapi import FastAPI, Depends, HTTPException, status
from pydantic import BaseModel
from typing import List, Optional
from enum import Enum

app = FastAPI()


class UserStatus(str, Enum):
    ACTIVE = "active"
    INACTIVE = "inactive"
    SUSPENDED = "suspended"


class SubscriptionStatus(str, Enum):
    ACTIVE = "active"
    INACTIVE = "inactive"
    EXPIRED = "expired"


class User(BaseModel):
    id: int
    username: str
    status: UserStatus
    subscription_status: SubscriptionStatus


class Project(BaseModel):
    id: int
    name: str
    description: Optional[str] = None
    owner_id: int
    is_active: bool


FAKE_USERS_DB = {
    1: User(
        id=1,
        username="active_user",
        status=UserStatus.ACTIVE,
        subscription_status=SubscriptionStatus.ACTIVE,
    ),
    2: User(
        id=2,
        username="inactive_user",
        status=UserStatus.INACTIVE,
        subscription_status=SubscriptionStatus.INACTIVE,
    ),
    3: User(
        id=3,
        username="suspended_user",
        status=UserStatus.SUSPENDED,
        subscription_status=SubscriptionStatus.ACTIVE,
    ),
}

FAKE_PROJECTS_DB = [
    Project(id=1, name="Project Alpha", description="First project", owner_id=1, is_active=True),
    Project(id=2, name="Project Beta", description="Second project", owner_id=1, is_active=True),
    Project(id=3, name="Project Gamma", description="Third project", owner_id=1, is_active=False),
    Project(id=4, name="Project Delta", description="Fourth project", owner_id=2, is_active=True),
]

FAKE_TOKENS_DB = {
    "token_active_user": 1,
    "token_inactive_user": 2,
    "token_suspended_user": 3,
}


def get_current_user(token: str = None) -> User:
    from fastapi.security import OAuth2PasswordBearer
    from fastapi import Header

    if token is None:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Not authenticated",
            headers={"WWW-Authenticate": "Bearer"},
        )

    user_id = FAKE_TOKENS_DB.get(token)
    if user_id is None:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Invalid authentication credentials",
            headers={"WWW-Authenticate": "Bearer"},
        )

    user = FAKE_USERS_DB.get(user_id)
    if user is None:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="User not found",
            headers={"WWW-Authenticate": "Bearer"},
        )

    return user


def get_current_user_from_header(authorization: Optional[str] = None) -> User:
    from fastapi import Header

    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Not authenticated",
            headers={"WWW-Authenticate": "Bearer"},
        )

    token = authorization.split(" ")[1]
    return get_current_user(token=token)


def require_active_account(user: User) -> User:
    if user.status != UserStatus.ACTIVE:
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail="Account is not active. Access denied.",
        )

    if user.subscription_status != SubscriptionStatus.ACTIVE:
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail="No active subscription. Access denied.",
        )

    return user


def get_authenticated_user(authorization: Optional[str] = None) -> User:
    from fastapi import Header
    return get_current_user_from_header(authorization=authorization)


def get_active_user(user: User = Depends(get_authenticated_user)) -> User:
    return require_active_account(user)


@app.get("/projects", response_model=List[Project], status_code=status.HTTP_200_OK)
def get_projects(
    authorization: Optional[str] = None,
):
    from fastapi import Header

    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Not authenticated",
            headers={"WWW-Authenticate": "Bearer"},
        )

    token = authorization.split(" ")[1]
    current_user = get_current_user(token=token)
    active_user = require_active_account(current_user)

    user_active_projects = [
        project
        for project in FAKE_PROJECTS_DB
        if project.owner_id == active_user.id and project.is_active
    ]

    return user_active_projects


@app.get("/projects/v2", response_model=List[Project], status_code=status.HTTP_200_OK)
async def get_projects_v2(
    authorization: Optional[str] = None,
):
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Not authenticated",
            headers={"WWW-Authenticate": "Bearer"},
        )

    token = authorization.replace("Bearer ", "")

    current_user = get_current_user(token=token)

    if current_user.status in (UserStatus.INACTIVE, UserStatus.SUSPENDED):
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail=f"Account is {current_user.status.value}. Access denied.",
        )

    if current_user.subscription_status != SubscriptionStatus.ACTIVE:
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail="No active subscription. Access denied.",
        )

    user_active_projects = [
        project
        for project in FAKE_PROJECTS_DB
        if project.owner_id == current_user.id and project.is_active
    ]

    return user_active_projects
