SCOPE_IMPLICATIONS = {
    "data:read": {"data:read"},
    "data:internal": {"data:read", "data:internal"},
    "data:admin": {"data:read", "data:internal", "data:admin"},
}


class User(BaseModel):
    username: str
    scopes: list[str]


class PublicSummaryResponse(BaseModel):
    access_level: str
