@Put(':projectId/settings')
@UseGuards(AuthGuard('jwt'))
async updateProjectSettings(
  @Param('projectId') projectId: string,
  @Body() updateProjectSettingsDto: UpdateProjectSettingsDto,
  @Req() req: Request & {
    user?: {
      roles?: Array<
        | string
        | {
            role?: string;
            name?: string;
            projectId?: string;
          }
      >;
    };
  },
) {
  const user = req.user;

  if (!user) {
    throw new UnauthorizedException();
  }

  const roles = user.roles ?? [];

  const hasOrgAdminRole = roles.some((role) => {
    if (typeof role === 'string') {
      return role === 'org_admin';
    }

    return role.role === 'org_admin' || role.name === 'org_admin';
  });

  const hasProjectOwnerRole = roles.some((role) => {
    if (typeof role === 'string') {
      return role === 'project_owner';
    }

    const roleName = role.role ?? role.name;

    return (
      roleName === 'project_owner' &&
      (!role.projectId || String(role.projectId) === String(projectId))
    );
  });

  if (!hasOrgAdminRole && !hasProjectOwnerRole) {
    throw new ForbiddenException();
  }

  return this.projectsService.updateSettings(projectId, updateProjectSettingsDto);
}
