  Param,
  Body,
  UseGuards,
  Request,
  HttpCode,
  HttpStatus,
} from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { SetMetadata } from '@nestjs/common';
import {
  Injectable,
  CanActivate,
  ExecutionContext,
  ForbiddenException,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';

export const ROLES_KEY = 'roles';
export const Roles = (...roles: string[]) => SetMetadata(ROLES_KEY, roles);

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector) {}

  canActivate(context: ExecutionContext): boolean {
    const requiredRoles = this.reflector.getAllAndOverride<string[]>(ROLES_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);

    if (!requiredRoles) {
      return true;
    }

    const { user } = context.switchToHttp().getRequest();

    if (!user) {
      return false;
    }

    const userRoles: string[] = user.roles || [];
    const hasRole = requiredRoles.some((role) => userRoles.includes(role));

    if (!hasRole) {
      throw new ForbiddenException(
        'You do not have permission to perform this action',
      );
    }

    return true;
  }
}

class UpdateProjectSettingsDto {
  name?: string;
  description?: string;
  visibility?: string;
  settings?: Record<string, unknown>;
}

class ProjectsService {
  async updateSettings(
    projectId: string,
    dto: UpdateProjectSettingsDto,
    userId: string,
  ) {
    return {
      id: projectId,
      ...dto,
      updatedBy: userId,
      updatedAt: new Date(),
    };
  }
}

@Controller('projects')
@UseGuards(AuthGuard('jwt'))
export class ProjectsController {
  constructor(private readonly projectsService: ProjectsService) {}

  @Put(':projectId/settings')
  @HttpCode(HttpStatus.OK)
  @UseGuards(RolesGuard)
  @Roles('project_owner', 'org_admin')
  async updateProjectSettings(
    @Param('projectId') projectId: string,
    @Body() updateProjectSettingsDto: UpdateProjectSettingsDto,
    @Request() req: { user: { id: string; roles: string[] } },
  ) {
    const updatedSettings = await this.projectsService.updateSettings(
      projectId,
      updateProjectSettingsDto,
      req.user.id,
    );

    return updatedSettings;
  }
}
