import {
  Body,
  Controller,
  ForbiddenException,
  Get,
  Param,
  Post,
  Put,
  Req,
  UseGuards,
} from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { Request } from 'express';
import { CreateEmployeeDto } from './dto/create-employee.dto';
import { UpdateSalaryDto } from './dto/update-salary.dto';
import { EmployeesService } from './employees.service';

type AuthenticatedRequest = Request & {
  user?: {
    id?: string | number;
    sub?: string | number;
    employeeId?: string | number;
    roles?: string[];
    role?: string;
  };
};

@Controller('employees')
@UseGuards(AuthGuard('jwt'))
export class EmployeesController {
  constructor(private readonly employeesService: EmployeesService) {}

  @Get()
  findAll(@Req() req: AuthenticatedRequest) {
    this.requireAnyRole(req, ['hr_staff', 'manager']);
    return this.employeesService.findAll();
  }

  @Get(':id')
  findOne(@Param('id') id: string, @Req() req: AuthenticatedRequest) {
    if (!this.hasAnyRole(req, ['hr_staff', 'manager']) && !this.isSelf(req, id)) {
      throw new ForbiddenException();
    }

    return this.employeesService.findOne(id);
  }

  @Put(':id/salary')
  updateSalary(
    @Param('id') id: string,
    @Body() updateSalaryDto: UpdateSalaryDto,
    @Req() req: AuthenticatedRequest,
  ) {
    this.requireAnyRole(req, ['hr_manager']);
    return this.employeesService.updateSalary(id, updateSalaryDto);
  }

  @Post()
  create(
    @Body() createEmployeeDto: CreateEmployeeDto,
    @Req() req: AuthenticatedRequest,
  ) {
    this.requireAnyRole(req, ['hr_manager']);
    return this.employeesService.create(createEmployeeDto);
  }

  private requireAnyRole(req: AuthenticatedRequest, roles: string[]): void {
    if (!this.hasAnyRole(req, roles)) {
      throw new ForbiddenException();
    }
  }

  private hasAnyRole(req: AuthenticatedRequest, roles: string[]): boolean {
    const user = req.user;

    if (!user) {
      return false;
    }

    const userRoles = Array.isArray(user.roles)
      ? user.roles
      : user.role
        ? [user.role]
        : [];

    return roles.some((role) => userRoles.includes(role));
  }

  private isSelf(req: AuthenticatedRequest, employeeId: string): boolean {
    const user = req.user;

    if (!user) {
      return false;
    }

    return [user.employeeId, user.id, user.sub]
      .filter((value) => value !== undefined && value !== null)
      .some((value) => String(value) === String(employeeId));
  }
}

